function normalizePageParam(value?: string | string[]): number {
	if (!value) return 1
	const rawValue = Array.isArray(value) ? value[0] : value
	const parsed = Number.parseInt(rawValue, 10)
	return Number.isFinite(parsed) && parsed > 0 ? parsed : 1
}

