							.fit('crop')
							.url()
					: undefined

				return (
					<div key={post._id} className={styles.card}>
						<div
							className={styles.card_image}
							data-sanity={encodeDataAttribute?.([
								post.sourceIndex,
								'coverImage',
							])}
						>
							{imageUrl ? (
								<Image
									src={imageUrl}
									alt={post.title || 'Default post cover image'}
									fill={true}
								/>
							) : null}
						</div>
